{
  "missing_information": [
    {
      "category": "decision",
      "gap": "No criteria defined for selecting which tool to use for a given wafer measurement",
      "why_it_matters": "Without knowing how tool selection is made, it is impossible to model the branching logic or assess whether selection can be automated"
    },
    {
      "category": "actor",
      "gap": "It is unclear who is responsible for preparing the wafer versus performing the measurement versus recording the result, and whether these are always the same engineer",
      "why_it_matters": "Automation opportunities depend on knowing where human handoffs occur and which roles are involved at each step"
    },
    {
      "category": "exception",
      "gap": "No information on what happens when a tool is unavailable, produces an out-of-range result, or fails mid-measurement",
      "why_it_matters": "Exception paths are common automation blockers and must be mapped to build a robust workflow model"
    },
    {
      "category": "output",
      "gap": "The format, destination, and required content of the recorded result are not specified",
      "why_it_matters": "Knowing what constitutes a completed record and where it is stored is essential for assessing data capture and downstream integration"
    },
    {
      "category": "manual_effort",
      "gap": "The specific preparation steps that differ by tool are not described, making it unclear how much manual effort is involved per tool type",
      "why_it_matters": "Tool-specific manual steps are prime candidates for automation, but they cannot be evaluated without knowing what those steps are"
    },
    {
      "category": "integration_constraint",
      "gap": "It is unknown whether measurement tools output data digitally and whether that data flows automatically into any recording or data management system",
      "why_it_matters": "If tool output is manual or analog, the integration path for automation is fundamentally different than if a digital interface already exists"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What determines which measurement tool is selected for a given wafer — for example, is the choice based on wafer type, measurement parameter, tool availability, or engineer preference?",
      "targets": ["decision"]
    },
    {
      "id": "Q2",
      "question": "For a representative tool, can you walk through each preparation step the engineer performs before the measurement begins?",
      "targets": ["manual_effort"]
    },
    {
      "id": "Q3",
      "question": "When the engineer records the measurement result, what exactly is captured, in what format, and in which system or document does it get stored?",
      "targets": ["output"]
    },
    {
      "id": "Q4",
      "question": "Do the measurement tools output results digitally in a way that can be read by another system, or does the engineer manually transcribe the reading?",
      "targets": ["integration_constraint"]
    },
    {
      "id": "Q5",
      "question": "If a tool is unavailable or produces a result that appears incorrect, what does the engineer do next?",
      "targets": ["exception"]
    },
    {
      "id": "Q6",
      "question": "Is there more than one person involved across the preparation, measurement, and result-recording steps, or does a single engineer own the entire sequence end to end?",
      "targets": ["actor"]
    }
  ]
}
